WITH hc AS (SELECT c.tconst FROM credits c JOIN people p ON p.nconst=c.nconst WHERE p.name='Tom Hanks' AND c.category IN ('actor','actress')),
sd AS (SELECT c.tconst FROM credits c JOIN people p ON p.nconst=c.nconst WHERE p.name='Steven Spielberg' AND c.category='director')
SELECT m.tconst, m.title, m.year FROM movies m WHERE m.tconst IN (SELECT tconst FROM hc) AND m.tconst IN (SELECT tconst FROM sd) ORDER BY m.year;
